style.css:
@-moz-document domain("open.spotify.com") {
/* Fondo con imagen y degradado rosa */
    body, .Root__main-view {
        background: linear-gradient(rgba(13,11,20,0.85), rgba(13,11,20,0.85)),
            url("https://i.imgur.com/ExamplePink.jpg") center / cover no-repeat !important;
        color: #ffc3ec !important;
        font-family: 'Poppins', sans-serif !important;
    }

    .Root__nav-bar, .Root__left-sidebar {
        background-color: rgba(26,19,31,0.9) !important;
    }

    .Root__now-playing-bar {
        background-color: rgba(26,14,24,0.9) !important;
        border-top: 1px solid #ff79c6 !important;
    }

    .track-info__name a {
        color: #ff9fd0 !important;
        font-weight: bold;
    }

    .track-info__artists a {
        color: #ffb6e6 !important;
    }

    button, .player-controls__buttons > * {
        color: #ffc3ec !important;
    }

    button:hover, .tracklist-row:hover {
        background-color: rgba(56,30,42,0.2) !important;
    }

    .playback-bar__progress-bar {
        background-color: #ffaad433 !important;
    }
    svg {
        fill: #ffc3ec !important;
    }
    [data-testid="ad-slot"] {
        display: none !important;
    }

    ::-webkit-scrollbar {
        width: 8px;
    }
    ::-webkit-scrollbar-track {
        background: rgba(26,19,31,0.9);
    }
    ::-webkit-scrollbar-thumb {
        background-color: #ff7ab3;
        border-radius: 10px;
    }
}
